<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_roles(['pengguna']);require __DIR__.'/../../app/helpers/layout.php';$error=null;if(is_post()){csrf_check();try{$title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$isbn=trim($_POST['isbn']??'');$year=(int)($_POST['publication_year']??0);$category=(int)($_POST['category_id']??0);$publisherName=trim($_POST['publisher']??'');$pages=(int)($_POST['pages']??0);$language=trim($_POST['language']??'Indonesia');$description=trim($_POST['description']??'');if(!$title||!$author)throw new RuntimeException('Judul dan penulis wajib diisi.');$cid=$category?:null;$pid=null;if($publisherName){$pdo->prepare('INSERT IGNORE INTO publishers(name) VALUES(?)')->execute([$publisherName]);$q=$pdo->prepare('SELECT id FROM publishers WHERE name=?');$q->execute([$publisherName]);$pid=(int)$q->fetchColumn();}$cover=save_upload($_FILES['cover']??[], 'uploads/books', ['jpg','jpeg','png','webp'],5242880);$pdf=save_upload($_FILES['pdf']??[], 'uploads/books', ['pdf'],20971520);$st=$pdo->prepare("INSERT INTO books(submitted_by,category_id,publisher_id,isbn,title,author,publication_year,language,pages,description,cover,stock_total,stock_available,status,approval_status,file_path,submitted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,1,1,'tersedia','menunggu',?,NOW())");$st->execute([$u['id'],$cid,$pid,$isbn?:null,$title,$author,$year?:null,$language,$pages?:null,$description,$cover,$pdf]);$id=(int)$pdo->lastInsertId();submission_history($pdo,$u['id'],'buku',$id,'diajukan','Pengajuan buku dibuat');notify_user($pdo,$u['id'],'Buku menunggu verifikasi','Pengajuan buku “'.$title.'” sedang menunggu verifikasi.');flash('success','Buku berhasil diajukan dan menunggu verifikasi.');redirect('/pengguna/riwayat/index.php');}catch(Throwable $e){$error=$e->getMessage();}}render_start('Tambah Buku','Pengajuan buku baru',$u);dashboard_nav('pengguna');render_mid('Tambah Buku','Status awal: Menunggu Verifikasi',$u);if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card"><?=csrf_input()?><div class="form-grid"><div class="form-group"><label>Judul Buku</label><input class="input" name="title" required></div><div class="form-group"><label>Penulis</label><input class="input" name="author" required></div><div class="form-group"><label>Penerbit</label><input class="input" name="publisher"></div><div class="form-group"><label>Tahun Terbit</label><input class="input" type="number" name="publication_year" min="1900" max="2100"></div><div class="form-group"><label>ISBN</label><input class="input" name="isbn"></div><div class="form-group"><label>Kategori</label><select name="category_id"><option value="0">Pilih kategori</option><?php foreach($pdo->query('SELECT id,name FROM book_categories ORDER BY name') as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Jumlah Halaman</label><input class="input" type="number" name="pages" min="1"></div><div class="form-group"><label>Bahasa</label><input class="input" name="language" value="Indonesia"></div></div><div class="form-group" style="margin-top:14px"><label>Deskripsi</label><textarea name="description" rows="6"></textarea></div><div class="form-grid" style="margin-top:14px"><div class="form-group"><label>Cover (JPG/PNG/WebP, max 5 MB)</label><input class="input" type="file" name="cover" accept="image/*"></div><div class="form-group"><label>File PDF (max 20 MB)</label><input class="input" type="file" name="pdf" accept="application/pdf"></div></div><div style="margin-top:18px"><button class="btn btn-primary">Kirim Pengajuan</button><a class="btn btn-light" style="margin-left:6px" href="/pengguna/tambah/index.php">Batal</a></div></form><?php render_end(); ?>
